def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'

    opp_def = 0
    my_def = 0
    for i in range(n):
        my, opp = history[i]
        if opp == 'D':
            opp_def += 1
        if my == 'D':
            my_def += 1

    if opp_def == 0:
        return 'C'

    last_my, last_opp = history[-1]

    # Detect if opponent is in a cooperative recovery phase after our defection.
    # Cooperate immediately when they showed softness (D then C) to avoid
    # getting stuck in long mutual defection spirals.
    if last_opp == 'C':
        if last_my == 'D':
            # We defected and they cooperated - reward them, don't exploit.
            return 'C'
        if n >= 2 and history[-2][1] == 'D':
            # They defected then cooperated - accept the olive branch.
            return 'C'
        # If they've been broadly cooperative, keep cooperating.
        if opp_def * 3 <= n:
            return 'C'

    if last_opp == 'D':
        # Retaliate, but if we've been the recent aggressor, try to reset.
        if last_my == 'D':
            # We are in a DD chain. Give a deterministic peace offering
            # after a short punishment to break the cycle quickly.
            if n >= 2 and history[-2][1] == 'D':
                if n >= 3 and history[-3][1] == 'D':
                    return 'C'
            return 'D'
        # They defected on our cooperation: punish once.
        return 'D'

    if opp_def * 4 <= n:
        return 'C'
    if opp_def * 2 >= n:
        return 'D'
    return 'C'
